6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>}
8	 * where YY is the last two digits of the {@code registrationDate} year
9	 * (e.g. {@code SMI-0007-M26}). Runs after the customer code and registration date have
10	 * been assigned.
11	 */
12	public class AssignMembershipNumber {
13	
14	    public void service(@Val Owner owner) {
15	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
16	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
17	    }
18	}
